function toAssignmentCandidate(item) {
  return {
    user: item.user,
    lastAssignment: item.history.lastAssignment,
    allAssignments: item.history.allAssignments,
    dateLastAssignment: item.history.dateLastAssignment,
    daysSinceLastIntervention: item.history.daysSinceLastIntervention
  };
}

// src/app/shared/components/assignment-source/wol-preview-url.util.ts
function isWolPreviewUrl(value) {
  try {
    const url = new URL(value);
    return url.protocol === "https:" && url.hostname === "wol.jw.org" && !url.username && !url.password && !url.port;
  } catch {
    return false;
  }
}

